<script setup lang="ts">
import { computed,onMounted,onBeforeUnmount,reactive,ref,watch } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessage,ElMessageBox } from 'element-plus';import { Plus,Refresh,Search } from '@element-plus/icons-vue';import type { components } from '@ism/api-client';import { useSessionStore } from '../stores/session';
import PersonalTableViews from '../components/PersonalTableViews.vue';
type Column=components['schemas']['PersonalTableColumn'];type Definition=components['schemas']['PersonalTableColumnDefinition'];
const personDefinitions:Definition[]=[{key:'code',label:'人员编码',required:true,width:140},{key:'name',label:'人员/供应商',required:true,width:230},{key:'idNumberMasked',label:'证件号码',required:false,width:180},{key:'tradeType',label:'工种',required:false,width:130},{key:'projectCode',label:'所属项目',required:false,width:140},{key:'status',label:'状态',required:false,width:100}];
const assetDefinitions:Definition[]=[{key:'code',label:'资产编码',required:true,width:140},{key:'name',label:'资产/供应商',required:true,width:230},{key:'type',label:'类型',required:false,width:100},{key:'plateNo',label:'车牌号',required:false,width:130},{key:'projectCode',label:'所属项目',required:false,width:140},{key:'status',label:'状态',required:false,width:100}];
const personColumns=ref<Column[]>(personDefinitions.map(c=>({key:c.key,visible:true,width:c.width}))),assetColumns=ref<Column[]>(assetDefinitions.map(c=>({key:c.key,visible:true,width:c.width})));
type Person=components['schemas']['SupplierPerson'];type Asset=components['schemas']['SupplierAsset'];type Supplier=components['schemas']['SupplierSummary'];type Project=components['schemas']['ProjectSummary'];
const session=useSessionStore(),route=useRoute(),router=useRouter();const tab=computed(()=>route.meta.tab as 'persons'|'assets');const loading=ref(false),dialog=ref(false),total=ref(0);const persons=ref<Person[]>([]),assets=ref<Asset[]>([]),suppliers=ref<Supplier[]>([]),projects=ref<Project[]>([]);const query=reactive({keyword:'',status:'',page:0,size:20});
const personForm=reactive({code:'',name:'',supplierId:'',projectId:'',idType:'NATIONAL_ID' as components['schemas']['IdType'],idNumber:'',mobile:'',jobTitle:'',tradeType:'',specialWorkType:'' as ''|components['schemas']['SpecialWorkType'],entryDate:''});
const assetForm=reactive({code:'',name:'',supplierId:'',projectId:'',type:'VEHICLE' as components['schemas']['AssetType'],plateNo:'',serialNo:'',brand:'',model:'',inspectionExpiryDate:'',fileId:''});
const personStatuses={PENDING:'待入场',ACTIVE:'在场',SUSPENDED:'已停用',EXITED:'已离场'},assetStatuses={PENDING:'待验收',AVAILABLE:'可用',IN_USE:'使用中',MAINTENANCE:'维修中',RETIRED:'已退役'},assetTypes={VEHICLE:'车辆',EQUIPMENT:'设备',TOOL:'工器具'};
const availableProjects=computed(()=>projects.value.filter(x=>x.supplierId===(tab.value==='persons'?personForm.supplierId:assetForm.supplierId)));
let requestVersion=0;
async function load(){
  const version=++requestVersion,currentTab=tab.value;loading.value=true;
  const params={keyword:query.keyword||undefined,page:query.page,size:query.size};
  try{
    if(currentTab==='persons'){
      const {data,error}=await session.client.GET('/resources/persons',{params:{query:{...params,status:(query.status||undefined) as components['schemas']['PersonStatus']|undefined}}});
      if(version!==requestVersion||currentTab!==tab.value)return;
      if(error||!data?.data){persons.value=[];total.value=0;ElMessage.error(error?.error.message??'人员台账加载失败');return;}
      persons.value=data.data.items;total.value=data.data.total;
    }else{
      const {data,error}=await session.client.GET('/resources/assets',{params:{query:{...params,status:(query.status||undefined) as components['schemas']['AssetStatus']|undefined}}});
      if(version!==requestVersion||currentTab!==tab.value)return;
      if(error||!data?.data){assets.value=[];total.value=0;ElMessage.error(error?.error.message??'资产台账加载失败');return;}
      assets.value=data.data.items;total.value=data.data.total;
    }
  }catch{
    if(version!==requestVersion||currentTab!==tab.value)return;
    persons.value=[];assets.value=[];total.value=0;ElMessage.error('台账加载失败，请重试');
  }finally{if(version===requestVersion)loading.value=false;}
}
async function openCreate(){const [s,p]=await Promise.all([session.client.GET('/suppliers',{params:{query:{status:'ACTIVE',page:0,size:100}}}),session.client.GET('/projects',{params:{query:{page:0,size:100}}})]);suppliers.value=s.data?.data?.items??[];projects.value=p.data?.data?.items??[];Object.assign(personForm,{code:'',name:'',supplierId:'',projectId:'',idType:'NATIONAL_ID',idNumber:'',mobile:'',jobTitle:'',tradeType:'',specialWorkType:'',entryDate:''});Object.assign(assetForm,{code:'',name:'',supplierId:'',projectId:'',type:'VEHICLE',plateNo:'',serialNo:'',brand:'',model:'',inspectionExpiryDate:'',fileId:''});dialog.value=true;}
async function save(){if(tab.value==='persons'){const f=personForm;if(!f.code||!f.name||!f.supplierId||!f.idNumber){ElMessage.warning('请完整填写人员必填项');return;}const {error}=await session.client.POST('/resources/persons',{body:{...f,projectId:f.projectId||undefined,mobile:f.mobile||undefined,jobTitle:f.jobTitle||undefined,tradeType:f.tradeType||undefined,specialWorkType:f.specialWorkType||undefined,entryDate:f.entryDate||undefined,version:0}});if(error){ElMessage.error(error.error.message);return;}}else{const f=assetForm;if(!f.code||!f.name||!f.supplierId||(f.type==='VEHICLE'&&!f.plateNo)){ElMessage.warning('请完整填写车辆设备必填项');return;}const {error}=await session.client.POST('/resources/assets',{body:{...f,projectId:f.projectId||undefined,plateNo:f.plateNo||undefined,serialNo:f.serialNo||undefined,brand:f.brand||undefined,model:f.model||undefined,inspectionExpiryDate:f.inspectionExpiryDate||undefined,fileId:f.fileId||undefined,version:0}});if(error){ElMessage.error(error.error.message);return;}}dialog.value=false;ElMessage.success('登记成功');await load();}
async function personStatus(row:Person,status:components['schemas']['PersonStatus']){let reason:string|undefined;if(status==='SUSPENDED'||status==='EXITED')reason=(await ElMessageBox.prompt('请输入变更原因','人员状态',{inputPattern:/.+/})).value;else await ElMessageBox.confirm(`确认变更为“${personStatuses[status]}”？`,'状态确认');const {error}=await session.client.POST('/resources/persons/{id}/status',{params:{path:{id:row.id}},body:{status,reason,version:row.version}});if(error)ElMessage.error(error.error.message);else await load();}
async function assetStatus(row:Asset,status:components['schemas']['AssetStatus']){let reason:string|undefined;if(status==='MAINTENANCE'||status==='RETIRED')reason=(await ElMessageBox.prompt('请输入变更原因','资产状态',{inputPattern:/.+/})).value;else await ElMessageBox.confirm(`确认变更为“${assetStatuses[status]}”？`,'状态确认');const {error}=await session.client.POST('/resources/assets/{id}/status',{params:{path:{id:row.id}},body:{status,reason,version:row.version}});if(error)ElMessage.error(error.error.message);else await load();}
async function handover(row:Asset){try{const recipient=(await ElMessageBox.prompt('填写接收人或接收单位','交接离场',{inputPattern:/\S/,inputErrorMessage:'接收人不能为空'})).value;const note=(await ElMessageBox.prompt('填写交接清单、资产状况及离场说明；完成后不能再次投入使用','确认交接',{inputPattern:/\S/,inputErrorMessage:'交接说明不能为空'})).value;const {error}=await session.client.POST('/resources/assets/{id}/handover',{params:{path:{id:row.id}},body:{recipient,note,version:row.version}});if(error)ElMessage.error(error.error.message);else{ElMessage.success('交接离场已记录');await load();}}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error('交接失败，请重试');}}
function switchTab(name:string){void router.push(name==='persons'?'/resources/persons':'/resources/assets');}watch(()=>route.path,()=>{query.status='';query.page=0;query.keyword=typeof route.query.keyword==='string'?route.query.keyword.slice(0,100):'';dialog.value=false;persons.value=[];assets.value=[];total.value=0;void load();});onMounted(()=>{query.keyword=typeof route.query.keyword==='string'?route.query.keyword.slice(0,100):'';void load();});onBeforeUnmount(()=>{requestVersion++;});
</script>
<template><div class="page"><div class="page-heading"><div><h1>{{tab==='persons'?'供应商人员':'车辆设备'}}</h1><p>{{tab==='persons'?'统一登记承包商入场人员、工种和项目归属':'管理车辆、设备和工器具的验收与使用状态'}}</p></div><el-button type="primary" :icon="Plus" @click="openCreate">{{tab==='persons'?'登记人员':'登记资产'}}</el-button></div><el-tabs :model-value="tab" @tab-change="switchTab"><el-tab-pane label="供应商人员" name="persons"/><el-tab-pane label="车辆设备" name="assets"/></el-tabs>
<el-card shadow="never" class="filter-card"><el-form inline><el-form-item label="关键词"><el-input v-model="query.keyword" clearable :prefix-icon="Search" placeholder="编码、名称、供应商"/></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable placeholder="全部状态" style="width:150px"><el-option v-for="(name,key) in (tab==='persons'?personStatuses:assetStatuses)" :key="key" :label="name" :value="key"/></el-select></el-form-item><el-button type="primary" @click="query.page=0;load()">查询</el-button><el-button :icon="Refresh" @click="query.keyword='';query.status='';query.page=0;load()">重置</el-button></el-form></el-card>
<el-card v-if="tab==='persons'" shadow="never" class="table-card"><PersonalTableViews key="resource.person" table-key="resource.person" :defaults="personDefinitions" @change="personColumns=$event"/><el-table :key="personColumns.map(c=>c.key+':'+c.visible+':'+c.width).join('|')" v-loading="loading" :data="persons"><el-table-column v-for="column in personColumns.filter(c=>c.visible)" :key="column.key" :label="personDefinitions.find(c=>c.key===column.key)?.label" :width="column.width"><template #default="{row}"><template v-if="column.key==='name'"><strong>{{row.name}}</strong><div class="subtext">{{row.supplierName}}</div></template><el-tag v-else-if="column.key==='status'">{{personStatuses[row.status as keyof typeof personStatuses]}}</el-tag><template v-else>{{row[column.key]??'—'}}</template></template></el-table-column><el-table-column label="操作" width="230" fixed="right"><template #default="{row}"><el-button link type="primary" @click="router.push({path:'/safety/credentials',query:{personId:row.id}})">培训凭证</el-button><el-button v-if="row.status==='PENDING'||row.status==='SUSPENDED'" link type="primary" @click="personStatus(row,'ACTIVE')">启用</el-button><el-button v-if="row.status==='ACTIVE'" link type="warning" @click="personStatus(row,'SUSPENDED')">停用</el-button><el-button v-if="row.status!=='EXITED'" link type="danger" @click="personStatus(row,'EXITED')">离场</el-button></template></el-table-column></el-table></el-card>
<el-card v-else shadow="never" class="table-card"><PersonalTableViews key="resource.asset" table-key="resource.asset" :defaults="assetDefinitions" @change="assetColumns=$event"/><el-table :key="assetColumns.map(c=>c.key+':'+c.visible+':'+c.width).join('|')" v-loading="loading" :data="assets"><el-table-column v-for="column in assetColumns.filter(c=>c.visible)" :key="column.key" :label="assetDefinitions.find(c=>c.key===column.key)?.label" :width="column.width"><template #default="{row}"><template v-if="column.key==='name'"><strong>{{row.name}}</strong><div class="subtext">{{row.supplierName}}</div></template><template v-else-if="column.key==='type'">{{assetTypes[row.type as keyof typeof assetTypes]}}</template><el-tag v-else-if="column.key==='status'">{{assetStatuses[row.status as keyof typeof assetStatuses]}}</el-tag><template v-else>{{row[column.key]??'—'}}</template></template></el-table-column><el-table-column label="交接离场" width="180"><template #default="{row}"><el-tooltip v-if="row.handedOverAt" :content="`${row.handoverRecipient}：${row.handoverNote}`"><span>{{row.handedOverAt}}</span></el-tooltip><el-button v-else :disabled="row.status==='IN_USE'" link type="primary" @click="handover(row)">交接离场</el-button></template></el-table-column><el-table-column label="操作" width="230" fixed="right"><template #default="{row}"><el-button v-if="!row.handedOverAt && (row.status==='PENDING'||row.status==='MAINTENANCE'||row.status==='IN_USE')" link type="primary" @click="assetStatus(row,'AVAILABLE')">可用</el-button><el-button v-if="!row.handedOverAt && (row.status==='AVAILABLE')" link type="success" @click="assetStatus(row,'IN_USE')">投入使用</el-button><el-button v-if="!row.handedOverAt && (row.status==='AVAILABLE'||row.status==='IN_USE')" link type="warning" @click="assetStatus(row,'MAINTENANCE')">维修</el-button><el-button v-if="!row.handedOverAt && (row.status!=='RETIRED'&&row.status!=='IN_USE')" link type="danger" @click="assetStatus(row,'RETIRED')">退役</el-button></template></el-table-column></el-table></el-card>
<el-dialog v-model="dialog" :title="tab==='persons'?'登记供应商人员':'登记车辆设备'" width="720px"><el-form v-if="tab==='persons'" label-position="top"><el-row :gutter="18"><el-col :span="12"><el-form-item label="人员编码 *"><el-input v-model="personForm.code"/></el-form-item></el-col><el-col :span="12"><el-form-item label="姓名 *"><el-input v-model="personForm.name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="供应商 *"><el-select v-model="personForm.supplierId" filterable style="width:100%"><el-option v-for="s in suppliers" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="所属项目"><el-select v-model="personForm.projectId" clearable style="width:100%"><el-option v-for="p in availableProjects" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="证件类型"><el-select v-model="personForm.idType"><el-option label="居民身份证" value="NATIONAL_ID"/><el-option label="护照" value="PASSPORT"/><el-option label="其他" value="OTHER"/></el-select></el-form-item></el-col><el-col :span="16"><el-form-item label="证件号码 *"><el-input v-model="personForm.idNumber"/></el-form-item></el-col><el-col :span="8"><el-form-item label="手机"><el-input v-model="personForm.mobile"/></el-form-item></el-col><el-col :span="8"><el-form-item label="岗位"><el-input v-model="personForm.jobTitle"/></el-form-item></el-col><el-col :span="8"><el-form-item label="工种"><el-input v-model="personForm.tradeType"/></el-form-item></el-col><el-col :span="12"><el-form-item label="特种作业类型"><el-select v-model="personForm.specialWorkType" clearable placeholder="普通岗位无需选择" style="width:100%"><el-option label="电工作业" value="ELECTRICAL"/><el-option label="焊接作业" value="WELDING"/><el-option label="高处作业" value="WORK_AT_HEIGHT"/><el-option label="其他" value="OTHER"/></el-select></el-form-item></el-col></el-row></el-form><el-form v-else label-position="top"><el-row :gutter="18"><el-col :span="12"><el-form-item label="资产编码 *"><el-input v-model="assetForm.code"/></el-form-item></el-col><el-col :span="12"><el-form-item label="资产名称 *"><el-input v-model="assetForm.name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="供应商 *"><el-select v-model="assetForm.supplierId" filterable style="width:100%"><el-option v-for="s in suppliers" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="所属项目"><el-select v-model="assetForm.projectId" clearable style="width:100%"><el-option v-for="p in availableProjects" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="资产类型"><el-select v-model="assetForm.type"><el-option label="车辆" value="VEHICLE"/><el-option label="设备" value="EQUIPMENT"/><el-option label="工器具" value="TOOL"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="车牌号"><el-input v-model="assetForm.plateNo"/></el-form-item></el-col><el-col :span="8"><el-form-item label="出厂编号"><el-input v-model="assetForm.serialNo"/></el-form-item></el-col><el-col :span="8"><el-form-item label="品牌"><el-input v-model="assetForm.brand"/></el-form-item></el-col><el-col :span="8"><el-form-item label="型号"><el-input v-model="assetForm.model"/></el-form-item></el-col><el-col :span="8"><el-form-item label="检验到期日"><el-date-picker v-model="assetForm.inspectionExpiryDate" value-format="YYYY-MM-DD"/></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">确认登记</el-button></template></el-dialog><el-pagination style="margin-top:16px" :current-page="query.page+1" :total="total" :page-size="query.size" layout="total, prev, pager, next" @current-change="(page:number)=>{query.page=page-1;load()}"/></div></template>
